import{_ as a,c as i,o as e,ag as o}from"./chunks/framework.CPtCmog4.js";const t="/assets/1745463434305.gAdpv9RU.jpg",h=JSON.parse('{"title":"DNS","description":"","frontmatter":{},"headers":[],"relativePath":"network/DNS.md","filePath":"network/DNS.md","lastUpdated":1780143966000}'),r={name:"network/DNS.md"};function s(n,l,d,S,N,D){return e(),i("div",null,l[0]||(l[0]=[o('<h1 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;DNS&quot;">​</a></h1><p><img src="'+t+'" alt=""></p><h2 id="什么是dns" tabindex="-1">什么是DNS <a class="header-anchor" href="#什么是dns" aria-label="Permalink to &quot;什么是DNS&quot;">​</a></h2><p>Domain Name System 域名解析系统，在网络中提供域名和IP地址之间互相解析的<strong>应用层</strong>服务。</p><h2 id="域名-ip映射的意义" tabindex="-1">域名-&gt;IP映射的意义 <a class="header-anchor" href="#域名-ip映射的意义" aria-label="Permalink to &quot;域名-&gt;IP映射的意义&quot;">​</a></h2><ul><li>方便记忆：记住一位朋友的名字显然比记住他的身份证号要容易得多。对于一个网站来说IP相当于身份证号，而域名就相当于名字。域名更容易被用户记住，IP更适合计算机处理。</li><li>灵活：IP可以动态变化，域名可以绑定多个IP。同时也为CDN服务提供基础。</li><li>安全性：DNS服务商家提供可信的域名解析服务，防止用户的权益在非法网站上受到侵害。</li></ul><h2 id="dns解析过程" tabindex="-1">DNS解析过程 <a class="header-anchor" href="#dns解析过程" aria-label="Permalink to &quot;DNS解析过程&quot;">​</a></h2><h3 id="多级服务" tabindex="-1">多级服务 <a class="header-anchor" href="#多级服务" aria-label="Permalink to &quot;多级服务&quot;">​</a></h3><p>计算机网络中存在着诸多DNS服务器（多级缓存），从小到大：</p><ul><li>浏览器DNS缓存</li><li>操作系统DNS缓存</li><li>本地host文件</li><li>本地DNS服务器（由ISP提供或手动配置，如 <code>8.8.8.8</code>）</li><li>根DNS服务器（全球13组，管理顶级域名）</li><li>顶级域名服务器（如 <code>.com</code>、<code>.cn</code>、<code>.org</code>）</li><li>权威DNS服务器（域名购买处的DNS服务器，存储具体的域名解析记录）</li></ul><h3 id="递归查询-vs-迭代查询" tabindex="-1">递归查询 vs 迭代查询 <a class="header-anchor" href="#递归查询-vs-迭代查询" aria-label="Permalink to &quot;递归查询 vs 迭代查询&quot;">​</a></h3><ul><li><p><strong>递归查询</strong>：客户端向本地DNS服务器发起请求，本地DNS服务器负责完整地解析出结果并返回。如果本地DNS服务器没有缓存，它会代替客户端向其他DNS服务器继续查询，直到获得最终结果。客户端只需等待一个最终应答。</p></li><li><p><strong>迭代查询</strong>：本地DNS服务器向其他DNS服务器查询时，对方如果不知道最终答案，会返回&quot;下一步应该去问谁&quot;（即指向下一个更接近答案的DNS服务器），由本地DNS服务器自己去继续查询。大多数DNS服务器之间的查询采用迭代方式。</p></li></ul><h3 id="完整解析流程示例" tabindex="-1">完整解析流程示例 <a class="header-anchor" href="#完整解析流程示例" aria-label="Permalink to &quot;完整解析流程示例&quot;">​</a></h3><p>以解析 <code>www.example.com</code> 为例：</p><ol><li>浏览器检查<strong>应用缓存</strong>，若有则直接使用</li><li>检查<strong>本地host文件</strong>（如 <code>/etc/hosts</code>），若有则直接使用</li><li>向<strong>本地DNS服务器</strong>发起递归查询</li><li>本地DNS服务器检查自身缓存，若有则返回</li><li>本地DNS服务器向<strong>根DNS服务器</strong>发起迭代查询，根服务器返回 <code>.com</code> 顶级DNS服务器地址</li><li>本地DNS服务器向<strong>顶级DNS服务器</strong>查询，顶级服务器返回 <code>example.com</code> 权威DNS服务器地址</li><li>本地DNS服务器向<strong>权威DNS服务器</strong>查询，权威服务器返回 <code>www.example.com</code> 的IP地址</li><li>本地DNS服务器将结果缓存并返回给客户端</li></ol><h2 id="域名配置" tabindex="-1">域名配置 <a class="header-anchor" href="#域名配置" aria-label="Permalink to &quot;域名配置&quot;">​</a></h2><ul><li>开发者在域名服务商购买的域名是顶级域名，域名服务商为购买的域名提供对应的解析服务。</li><li>域名解析配置有多种类型 <ul><li>AAAA：ipv6</li><li>A：ipv4</li><li>CNAME：另一个域名</li><li>MX：邮件交换记录，指向邮件服务器</li><li>NS：域名服务器记录，指定由哪些DNS服务器来解析该域名</li><li>TXT：文本记录，常用于域名验证（如SPF、DKIM）</li><li>SRV：服务记录，指定提供特定服务的服务器地址和端口</li></ul></li></ul><h2 id="大型分布式应用的dns" tabindex="-1">大型分布式应用的DNS <a class="header-anchor" href="#大型分布式应用的dns" aria-label="Permalink to &quot;大型分布式应用的DNS&quot;">​</a></h2><ul><li>为了响应速度，IP是动态的，会根据运营商、用户所在地等信息将DNS解析到距离用户最近的服务器上（即DNS智能解析/GSLB）。</li><li>根服务器不会暴露在公网上，用户能访问到的往往是反向代理服务器、防火墙服务器等。</li><li>CDN（内容分发网络）大量依赖DNS实现就近访问：用户请求域名时，DNS将域名解析为距用户最近的CDN节点IP。</li><li>DNS负载均衡：一个域名可以配置多个A记录，DNS服务器按照轮询等策略返回不同的IP，实现简单的负载均衡。</li></ul><h2 id="dns安全" tabindex="-1">DNS安全 <a class="header-anchor" href="#dns安全" aria-label="Permalink to &quot;DNS安全&quot;">​</a></h2><ul><li>DNS劫持：攻击者篡改DNS解析结果，将用户引导至恶意网站</li><li>DNS污染：在DNS查询过程中，伪造响应数据包返回错误的IP地址</li><li>DNSSEC：DNS安全扩展，通过数字签名验证DNS响应的真实性和完整性，防止DNS劫持和污染</li></ul>',21)]))}const u=a(r,[["render",s]]);export{h as __pageData,u as default};
